import datetime
import re

import pexpect
import time
import threading
from abc import ABCMeta, abstractmethod
from ta_tshark_json_parser.py3_string import py3_string
from ta_tshark_json_parser.tshark_field_parser import TsharkFieldParser
from ta_tshark_json_parser.logger_config import configure_logger
from ta_tshark_json_parser.submodule_ute_common_abstract_core.logger import get_logging_path
import psutil
import os


class InterfaceForTsharkDoesNotExist(Exception):
    pass


class TsharkSource(object):
    '''
    Specific message source that implements extracting tshark data from tshark stream with -T fields option
    '''
    DataTimeout = 0.1

    class DataSource(object):
        '''
        Stores connection and has read(chunk) method
        '''
        def __init__(self, connection):
            self.connection = connection

        def read(self, chunk=4096):
            """
            Read and return connection data of size == chunk
            """
            chunk_buff = ""
            if self.connection.isalive():
                try:
                    while len(chunk_buff) < chunk:
                        chunk_buff += py3_string(self.connection.read_nonblocking(size=chunk,
                                                                                  timeout=TsharkSource.DataTimeout))
                    return chunk_buff
                except pexpect.TIMEOUT:
                    return chunk_buff
            else:
                return None

    def __init__(self, queue, layer=None, duplicated_keys_handler=None):
        self.queue = queue
        self.logger = configure_logger('ta_tshark_json_parser.tshark_source.{}'
                                       .format(self.get_unique_logger_name()))
        self.is_running = threading.Event()
        self._source_started = threading.Semaphore(0)
        self._main_loop_finished = threading.Semaphore(0)
        self.tmp_file = None
        self.pcap_log_file_prefix = "ta_tshark_json_parser.{}".format(self.get_unique_logger_name())
        self.data_generator = TsharkFieldParser(layer=layer,
                                                stop_condition=self.is_running.is_set,
                                                duplicated_keys_handler=duplicated_keys_handler,
                                                logger_suffix=self.get_unique_logger_name()).iter_data_records
        self._connection = self.get_opened_connection()
        self._data_source = TsharkSource.DataSource(self._connection)
        self._start_in_separate_thread()

    def _start_in_separate_thread(self):
        threading.Thread(target=self.start).start()
        self._source_started.acquire()

    def _put_to_queue(self, *args):
        for arg in args:
            self.queue.put(arg)

    def check_interface(self, if_name):
        '''
        Raises exception when interface for tshark does not exists, otherwise does nothing.

        :param if_name:
        :return:
        '''
        if check_if_interface_exists(if_name):
            pass
        else:
            raise InterfaceForTsharkDoesNotExist("Interface: {} does not exist".format(if_name))

    def start(self):
        '''
        Starts MessageSource infinite loop.
        Infinite loop is composed of parsing data stream, creating UnparsedMessages and sending them to the output queue
        For loop is a generator and can be broken by changed stop condition.
        '''
        self.is_running.set()
        self._source_started.release()
        for data_record in self.data_generator(self._data_source):
            processed = self.process_data_record(data_record)
            if processed is not None:
                self._put_to_queue(processed)
        self._main_loop_finished.release()

    def stop(self):
        '''
        Stops message source loop and perfoms cleanup
        '''
        if self.is_running.is_set():
            self.is_running.clear()
            self._main_loop_finished.acquire()
            self._close_connection()

    def process_data_record(self, data_record):
        """
        Do some processing. Overload if neeeded.
        :param data_record:
        :return:
        """
        return data_record

    @abstractmethod
    def get_unique_logger_name(self):
        return None

    @abstractmethod
    def get_tshark_command(self):
        '''
        Should be implemented by deriving class to start tshark

        :return:  e.g. 'tshark -i eth4 -T pdml -Y iphy.ue_id'
        '''
        pass

    @abstractmethod
    def get_opened_connection(self):
        '''
        Returns established connection object to data stream (inheritance API)

        :return: connection
        '''
        pass

    def _get_tshark_command(self):
        user_tshark_cmd = self.get_tshark_command()
        self.logger.info('User specified command to start tshark: {}'.format(user_tshark_cmd))
        assert '-T json' in user_tshark_cmd, "Using '-T json' option is mandatory for json tshark"
        assert '-l' in user_tshark_cmd, "Using '-l' option is mandatory for json parser"
        return user_tshark_cmd

    def _get_plink_command(self):
        assert hasattr(self, 'remote_pass') and hasattr(self, 'remote_user') and hasattr(self, 'remote_ip'), \
            "Values for remote access: 'remote_pass, remote_user, remote_ip' must be specified"
        tshark_command = self._get_tshark_command()
        plink_command = 'plink -t -pw %s %s@%s \'%s\'' % (self.remote_pass, self.remote_user, self.remote_ip, tshark_command)
        return plink_command

    def get_opened_connection_local(self):
        '''
        Returns established connection object to data stream (inheritance API)

        :return: connection
        '''
        self.logger.info('Starting tshark connection locally using pexpect spawn')
        tshark_command = self._get_tshark_command()
        if '|' not in tshark_command:
            process = pexpect.spawn(tshark_command)
        else:
            process = pexpect.spawn('/bin/bash', ['-c', tshark_command])
        if '-r -' in tshark_command:
            try:
                process.expect('tcpdump: listening on')
            except Exception as e:
                self.logger.error(
                    '{} << failed to start with exception: {} and out string: {}'.format(self, e, process.readlines()))
            time.sleep(1)  # additional sleep for tshark to begin catching
            self.logger.debug('%s << started capturing tshark packets via remote tcpdump' % self)
        elif ' -i ' in tshark_command:  # means spying on network interface
            process.expect('Capturing on')
            self.logger.debug('%s << started capturing tshark packets' % self)
            time.sleep(1)  # additional sleep for tshark to begin catching
            try:
                process.expect('.pcapng', timeout=5)
                tmp_files_found = re.findall(r'\/tmp\/\S+', py3_string(process.before))
                assert len(tmp_files_found), 'Could not find tmp file in output'
                self.tmp_file = "{}.pcapng".format(tmp_files_found[0])
                self.logger.debug('Found tmp file for tshark: {}'.format(self.tmp_file))
            except pexpect.exceptions.TIMEOUT:
                self.logger.debug('Could not find .pcapng for this process')
            except AssertionError as e2:
                self.logger.debug('Could not find tmp pcap.ng files')
        else:
            time.sleep(1)
            self.logger.debug('%s << started reading tshark packets without any confirmation' % self)
        return process

    def get_opened_connection_remote(self):
        '''
        Returns established connection object to data stream (inheritance API)

        :return: connection
        '''
        self.logger.info('Starting tshark connection remotely using plink')
        process = pexpect.spawn(self._get_plink_command())
        process.expect('Capturing on')
        time.sleep(1)
        return process

    def _close_connection(self):
        '''
        Closes connection to data stream (inheritance API)
        '''
        self.logger.debug('Closing the connection')
        try:
            self._copy_tmp_tshark_file()
        except Exception as e_copy:
            self.logger.debug('Could not copy *pcapng file due to exception:\n{}'.format(e_copy))
        try:
            self._connection.close()
        except pexpect.ExceptionPexpect as exc:
            tshark_pid = self._connection.pid
            tshark_process = psutil.Process(tshark_pid)
            process_status = self._get_process_status(tshark_pid)
            tshark_cmdline = tshark_process.cmdline()
            if process_status != psutil.STATUS_ZOMBIE:
                # try kill it via psutil
                self._force_retry_kill(tshark_process)
                process_status = self._get_process_status(tshark_pid)
            if process_status == psutil.STATUS_DEAD:
                pass  # done, cleaned up
            elif process_status == psutil.STATUS_ZOMBIE:
                # on some TL pexpect can't kill tshark, it remains as zombie process but it is cleanedup at next TestCase start
                print("WARN: tshark process: PID = {}, status = {}, cmd = {}".format(tshark_pid, process_status, tshark_cmdline))
            else:
                print("killing tshark process failed: PID = {}, status = {}, cmd = {}".format(tshark_pid, process_status, tshark_cmdline))
                raise exc
        self.logger.debug('Connection closed')

    def _copy_tmp_tshark_file(self):
        '''
        Copying /tmp tshark file.
        Note: Files exists only when thark is running and will be automatically deleted when it closes, so file
        must be copied before closing.
        '''
        self.logger.debug('Started copying tmp pcap file before connection closes')
        if self.tmp_file is not None:
            timestamp = datetime.datetime.today().strftime('%Y%m%d_%H%M%S')
            log_path = get_logging_path()
            pcap_file_name = "{}_{}.pcapng".format(self.pcap_log_file_prefix, timestamp)
            dst_path = os.path.sep.join([log_path, pcap_file_name])
            if os.path.exists(dst_path):
                cmd = 'rm -rf {}'.format(dst_path)
                self.logger.debug('Dst path: {} already exists, removing by: {}'.format(dst_path, cmd))
                os.system(cmd)
            try:
                assert os.path.exists(self.tmp_file), 'tmp file: {} not exists in filesystem'.format(self.tmp_file)
                cmd = 'cp {} {}'.format(self.tmp_file, dst_path)
                self.logger.debug('Executing cmd to copy files: {}'.format(cmd))
                os.system(cmd)
            except Exception as e:
                self.logger.debug('Could not copy tmp pcap file due to exception: {}'.format(e))
        else:
            self.logger.debug('Not found any tmp files during tshark process start')

    def _force_retry_kill(self, tshark_process):
        tshark_process.terminate()
        gone, alive = psutil.wait_procs([tshark_process], timeout=3)
        for p in alive:
            p.kill()

    def _get_process_status(self, tshark_pid):
        try:
            tshark_process = psutil.Process(tshark_pid)
            return tshark_process.status()
        except psutil.NoSuchProcess:
            return psutil.STATUS_DEAD


def check_if_interface_exists(interface_name):
    '''
    Returns True if interface exists on machine when python runs, otherwise False.

    :param interface_name:
    :return:
    '''
    interface_name = str(interface_name)
    available_interfaces = os.listdir('/sys/class/net/')
    return True if interface_name in available_interfaces else False
